                    components.append((sum(px for px, _ in points) / len(points), sum(py for _, py in points) / len(points), len(points)))
        if not components:
            raise SystemExit(f"No reference anchors found on output page {page_index + 1}.")
        for _x, y, _size in components:
            candidates.append((page_index, y))
        del image, pixmap
    reference.close()
    if len(candidates) != questions:
        raise SystemExit(f"Reference contains {len(candidates)} anchors; expected {questions}.")
    labels: dict[int, tuple[int, float, float]] = {}
    for number, (page_index, y) in enumerate(candidates, start=1):
        labels[number] = (page_index, 0.0, y)
    return labels

